class Solution:
    def countSimilarPairs(self, words: List[str]) -> int:
        from collections import Counter
        cnt = Counter()
        for w in words:
            base = ord(w[0]) - 97
            cnt[tuple((ord(c) - 97 - base) % 26 for c in w)] += 1
        return sum(c * (c - 1) // 2 for c in cnt.values())

