class Solution {
public:
    int countSimilarPairs(vector<string>& words) {
        unordered_map<string, long long> cnt;
        for (auto& w : words) {
            int base = w[0] - 'a';
            string key;
            for (char c : w) key += char((c - 'a' - base + 26) % 26 + 'a');
            cnt[key]++;
        }
        long long ans = 0;
        for (auto& [k, c] : cnt) ans += c * (c - 1) / 2;
        return (int)ans;
    }
};

