class Solution {
    public int countSimilarPairs(String[] words) {
        Map<String, Long> cnt = new HashMap<>();
        for (String w : words) {
            int base = w.charAt(0) - 'a';
            StringBuilder sb = new StringBuilder();
            for (char c : w.toCharArray())
                sb.append((char) ('a' + (c - 'a' - base + 26) % 26));
            cnt.merge(sb.toString(), 1L, Long::sum);
        }
        long ans = 0;
        for (long c : cnt.values()) ans += c * (c - 1) / 2;
        return (int) ans;
    }
}

