        for i in range(n):
            for j in range(i + 1, n):
                a, b = words[i], words[j]
                d = (ord(b[0]) - ord(a[0])) % 26
                if all((ord(b[k]) - ord(a[k])) % 26 == d for k in range(len(a))):
