class Solution {
public:
    int countSimilarPairs(vector<string>& words) {
        int n = words.size(), ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) {
                int d = (words[j][0] - words[i][0] + 26) % 26;
                bool ok = true;
                for (int k = 0; k < (int)words[i].size(); k++)
                    if ((words[j][k] - words[i][k] + 26) % 26 != d) { ok = false; break; }
                if (ok) ans++;
            }
        return ans;
    }
};

